export class HeatMapChart {
    layoutService = inject(LayoutService);

    label = input<string>('Label');

    dataset = input<any[]>();

    conditions = input.required<any[]>();

    chart!: ChartJS;

    chartData: any;

    chartPlugins: any;

    chartOptions: any;

    chartEffect = effect(() => {
        this.layoutService.layoutConfig().darkTheme;
        this.dataset();
        setTimeout(() => this.initChart(), 150);
    });

    createChart() {
        const canvas = document.getElementById('heatmap') as HTMLCanvasElement | null;
        const ctx = canvas?.getContext('2d');
        if (!ctx) {
            return;
        }
        if (this.chart) {
            this.chart.destroy();
        }
        this.chart = new ChartJS(ctx, {
            type: 'matrix',
            data: this.chartData,
            options: this.chartOptions,
            plugins: this.chartPlugins
        });
    }

    initChart() {
        this.chartData = this.setChartData();
        this.chartPlugins = this.setChartPlugins();
        this.chartOptions = this.setChartOptions();
        this.createChart();
    }

    setChartPlugins() {
        return [];
    }

    chartBackgroundColor(c: any) {
        const rootStyles = getComputedStyle(document.documentElement);
        const value = c.dataset.data[c.dataIndex].v;

        const conditions = this.conditions();

        let backgroundColor = '--p-surface-800';

        for (const condition of conditions) {
            if (value >= condition.min && value <= condition.max) {
                backgroundColor = condition.color[this.layoutService.isDarkTheme() ? 'dark' : 'light'];
                break;
            }
        }
        return rootStyles.getPropertyValue(backgroundColor);
    }

    setChartData() {
        return {
