        const textColor = darkMode ? surface400 : surface950;

        return {
            animation: false,
            interaction: {
                intersect: false,
                mode: 'index'
            },
            responsive: true,
            maintainAspectRatio: false,
            layout: {
                padding: 0
            },
            events: [],
            plugins: {
                legend: {
                    display: false
                },
                tooltip: {
                    enabled: false
                }
            },
            scales: {
                x: {
                    type: 'time',
                    offset: true,
                    time: {
                        unit: 'week',
                        round: 'week',
                        isoWeekDay: 1,
                        displayFormats: {
                            week: 'MMM dd'
                        }
                    },
                    ticks: {
                        maxRotation: 0,
                        autoSkip: true,
                        font: {
                            size: 12
                        },
                        color: textColor
                    },
                    grid: {
                        display: false,
                        drawBorder: false,
                        tickLength: 0
                    },
                    border: {
                        display: false
                    }
                },
                y: {
