                                <p-accordionheader>
                                    <div class="flex items-center gap-4 px-4 lg:px-6">
                                        <h2 class="text-surface-900 dark:text-surface-0 text-lg font-semibold">{{ completedTasks().length }} Tasks Completed</h2>
                                    </div>
