                                    }
                                </p-avatargroup>
                            }
                        </div>
                    </div>

                    <!-- Mobile View -->
                    <div class="flex lg:hidden items-center justify-between">
                        <div class="flex items-center gap-2 flex-wrap">
                            @if (task.startDate) {
                                <div class="flex items-center gap-1">
                                    <i class="pi pi-calendar text-xs text-surface-500"></i>
                                    <p-tag [value]="task.startDate" severity="secondary" size="small" />
                                </div>
                            }

                            @if (task.startDate && task.endDate) {
                                <div class="text-surface-500 text-sm">-</div>
                            }

                            @if (task.endDate) {
                                <div class="flex items-center gap-1">
                                    <p-tag [value]="task.endDate" severity="secondary" size="small" />
                                </div>
                            }

                            @if ((task.startDate || task.endDate) && task.members?.length > 0) {
                                <div class="w-px h-3 bg-surface-200 dark:bg-surface-700"></div>
                            }

                            @if (task.members?.length > 0) {
                                <p-avatargroup>
                                    @for (member of task.members.slice(0, 3); track member.image) {
                                        <p-avatar [image]="'/demo/images/avatar/' + member.image" shape="circle" styleClass="border border-surface-0 dark:border-surface-900 w-6 h-6" />
                                    }
                                    @if (task.members.length > 3) {
                                        <p-avatar [label]="'+' + (task.members.length - 3)" shape="circle" styleClass="bg-primary-500 text-surface-0 border border-surface-0 dark:border-surface-900 w-6 h-6" />
                                    }
                                </p-avatargroup>
                            }
                        </div>
                    </div>

                    <div class="flex items-center gap-2 lg:ml-auto">
                        <p-button icon="pi pi-pencil" [text]="true" [rounded]="true" size="small" severity="secondary" styleClass="cursor-pointer" (onClick)="openEditTaskDrawer(task)" />
                        <p-button icon="pi pi-trash" [text]="true" [rounded]="true" size="small" severity="secondary" styleClass="cursor-pointer" (onClick)="deleteTask(task.id)" />
                    </div>
                </div>

                @if (!isLast) {
                    <div class="px-4 lg:px-14 py-2">
                        <div class="border-t border-dashed border-surface-200 dark:border-surface-700"></div>
                    </div>
                }
            </div>
        </ng-template>

        <!-- Completed Task Item Template -->
        <ng-template #taskItemCompleted let-task="task" let-isLast="isLast">
            <div class="flex flex-col">
                <div class="px-4 lg:px-8 pt-4 pb-2">
                    <div class="flex items-center gap-3">
                        <p-checkbox [(ngModel)]="task.completed" [binary]="true" [inputId]="'task-' + task.id" (onChange)="toggleTaskCompletion(task, task.completed)" />
                        <div class="text-surface-500 text-base font-medium leading-normal line-through flex-1">
                            {{ task.title }}
                        </div>
                    </div>
                    @if (task.description) {
                        <div class="text-surface-500 text-sm leading-tight line-clamp-3 pl-8 pt-1">
                            {{ task.description }}
                        </div>
                    }
                </div>

                <div class="pl-8 lg:pl-16 pr-4 lg:pr-14 pt-2 pb-4 flex flex-col lg:flex-row lg:items-center gap-3">
                    <!-- Desktop View -->
                    <div class="hidden lg:flex items-center gap-2 flex-1">
                        @if (task.startDate || task.endDate) {
                            @if (task.startDate) {
                                <div class="flex items-center gap-2">
                                    <span class="text-surface-500 text-base">Start</span>
                                    <p-tag [value]="task.startDate" severity="secondary" />
                                </div>
                            }

                            @if (task.startDate && task.endDate) {
                                <div class="w-px h-2.5 bg-surface-200 dark:bg-surface-700"></div>
                            }

                            @if (task.endDate) {
                                <div class="flex items-center gap-2">
                                    <span class="text-surface-500 text-base">End</span>
                                    <p-tag [value]="task.endDate" severity="secondary" />
                                </div>
                            }

                            @if (task.members?.length > 0) {
                                <div class="w-px h-2.5 bg-surface-200 dark:bg-surface-700"></div>
                            }
                        }

                        <div class="flex-1 flex items-start">
                            @if (task.members?.length > 0) {
                                <p-avatargroup>
                                    @for (member of task.members.slice(0, 5); track member.image) {
                                        <p-avatar [image]="'/demo/images/avatar/' + member.image" shape="circle" styleClass="border border-surface-0 dark:border-surface-900 w-6 h-6" />
                                    }
                                    @if (task.members.length > 5) {
                                        <p-avatar [label]="'+' + (task.members.length - 5)" shape="circle" styleClass="bg-primary-500 text-surface-0 border border-surface-0 dark:border-surface-900 w-6 h-6" />
                                    }
                                </p-avatargroup>
                            }
                        </div>
                    </div>

                    <!-- Mobile View -->
                    <div class="flex lg:hidden items-center justify-between">
                        <div class="flex items-center gap-2 flex-wrap">
                            @if (task.startDate) {
                                <div class="flex items-center gap-1">
                                    <i class="pi pi-calendar text-xs text-surface-500"></i>
                                    <p-tag [value]="task.startDate" severity="secondary" size="small" />
                                </div>
                            }

                            @if (task.startDate && task.endDate) {
                                <div class="text-surface-500 text-sm">-</div>
                            }

                            @if (task.endDate) {
                                <div class="flex items-center gap-1">
                                    <p-tag [value]="task.endDate" severity="secondary" size="small" />
                                </div>
                            }

                            @if ((task.startDate || task.endDate) && task.members?.length > 0) {
                                <div class="w-px h-3 bg-surface-200 dark:bg-surface-700"></div>
                            }

                            @if (task.members?.length > 0) {
                                <p-avatargroup>
                                    @for (member of task.members.slice(0, 3); track member.image) {
                                        <p-avatar [image]="'/demo/images/avatar/' + member.image" shape="circle" styleClass="border border-surface-0 dark:border-surface-900 w-6 h-6" />
                                    }
                                    @if (task.members.length > 3) {
                                        <p-avatar [label]="'+' + (task.members.length - 3)" shape="circle" styleClass="bg-primary-500 text-surface-0 border border-surface-0 dark:border-surface-900 w-6 h-6" />
                                    }
                                </p-avatargroup>
                            }
                        </div>
                    </div>

                    <div class="flex items-center gap-2 lg:ml-auto">
                        <p-button icon="pi pi-pencil" [text]="true" [rounded]="true" size="small" severity="secondary" styleClass="cursor-pointer" (onClick)="openEditTaskDrawer(task)" />
                        <p-button icon="pi pi-trash" [text]="true" [rounded]="true" size="small" severity="secondary" styleClass="cursor-pointer" (onClick)="deleteTask(task.id)" />
                    </div>
                </div>

                @if (!isLast) {
                    <div class="px-4 lg:px-14 py-2">
                        <div class="border-t border-dashed border-surface-200 dark:border-surface-700"></div>
                    </div>
                }
            </div>
        </ng-template>
    `
})
export class TaskList {
    activeFilter = signal<string>('All Tasks');
    searchQuery = model<string>('');
    openPanels = ['0', '1', '2'];
    isDrawerVisible = false;
    selectedTask: Task | null = null;
    drawerMode: 'create' | 'edit' = 'create';

    filterOptions = [
        { key: 'All Tasks', label: 'All', fullLabel: 'All Tasks', icon: 'pi pi-list', countKey: 'all' as const },
        { key: 'Pending', label: 'Pending', fullLabel: 'Pending', icon: 'pi pi-inbox', countKey: 'inbox' as const },
        { key: 'In Progress', label: 'In Progress', fullLabel: 'In Progress', icon: 'pi pi-clock', countKey: 'inProgress' as const },
        { key: 'Completed', label: 'Completed', fullLabel: 'Completed', icon: 'pi pi-check-circle', countKey: 'completed' as const }
    ];

    taskData = signal<Task[]>([
        { id: 1, title: 'Design a SaaS Platform UI', description: null, status: 'pending', completed: false, startDate: '12.01.2025', endDate: '24.01.2025', members: [{ image: 'amyelsner.png' }, { image: 'annafali.png' }] },
        { id: 2, title: 'Create an E-Commerce Landing Page', description: null, status: 'pending', completed: false, startDate: '02.01.2025', endDate: '28.01.2025', members: [{ image: 'amyelsner.png' }, { image: 'annafali.png' }] },
        {
            id: 3,
            title: 'Build an Educational Website UI',
            description: 'A clean, professional and fast information access interface will be designed for an education-oriented website.',
            status: 'pending',
            completed: false,
            startDate: '02.02.2025',
            endDate: '06.02.2025',
            members: [{ image: 'amyelsner.png' }, { image: 'annafali.png' }, { image: 'asiyajavayant.png' }, { image: 'bernardodominic.png' }]
        },
        { id: 4, title: 'Develop a Tech Startup Landing Page', description: null, status: 'pending', completed: false, startDate: '12.02.2025', endDate: '27.02.2025', members: [{ image: 'amyelsner.png' }, { image: 'annafali.png' }] },
        { id: 5, title: 'Design a Healthcare Landing Page', description: null, status: 'pending', completed: false, startDate: '09.02.2025', endDate: '17.02.2025', members: [{ image: 'amyelsner.png' }, { image: 'annafali.png' }] },
        { id: 6, title: 'Create a Finance Dashboard UI', description: null, status: 'in-progress', completed: false, startDate: '15.02.2025', endDate: '28.03.2025', members: [{ image: 'amyelsner.png' }, { image: 'annafali.png' }] },
        { id: 7, title: 'Design a Fashion Landing Page', description: null, status: 'in-progress', completed: false, startDate: '12.02.2025', endDate: '19.02.2025', members: [{ image: 'amyelsner.png' }, { image: 'annafali.png' }] },
        {
            id: 8,
            title: 'Develop a Gaming Platform UI',
            description: null,
            status: 'completed',
            completed: true,
            startDate: '02.02.2025',
            endDate: '06.02.2025',
            members: [{ image: 'amyelsner.png' }, { image: 'annafali.png' }, { image: 'asiyajavayant.png' }, { image: 'bernardodominic.png' }]
        },
        { id: 9, title: 'Create a Corporate Website Landing Page', description: null, status: 'completed', completed: true, startDate: '12.02.2025', endDate: '27.02.2025', members: [{ image: 'amyelsner.png' }, { image: 'annafali.png' }] },
        { id: 10, title: 'Design a Personal Blog Landing Page', description: null, status: 'completed', completed: true, startDate: '12.01.2025', endDate: '24.01.2025', members: [{ image: 'amyelsner.png' }, { image: 'annafali.png' }] }
    ]);

    filteredTasks = computed(() => {
        let tasks = this.taskData();

        if (this.searchQuery().trim()) {
            tasks = tasks.filter((task) => task.title.toLowerCase().includes(this.searchQuery().toLowerCase()));
        }

        switch (this.activeFilter()) {
            case 'Pending':
                return tasks.filter((task) => task.status === 'pending');
            case 'In Progress':
                return tasks.filter((task) => task.status === 'in-progress');
            case 'Completed':
                return tasks.filter((task) => task.status === 'completed');
            default:
                return tasks;
        }
    });

    taskCounts = computed(() => ({
        all: this.taskData().length,
        inbox: this.taskData().filter((task) => task.status === 'pending').length,
        inProgress: this.taskData().filter((task) => task.status === 'in-progress').length,
        completed: this.taskData().filter((task) => task.status === 'completed').length
    }));

    pendingTasks = computed(() => this.filteredTasks().filter((task) => task.status === 'pending'));
    inProgressTasks = computed(() => this.filteredTasks().filter((task) => task.status === 'in-progress'));
    completedTasks = computed(() => this.filteredTasks().filter((task) => task.status === 'completed'));

    constructor(private confirmationService: ConfirmationService) {}

    toggleTaskCompletion(task: Task, completed: boolean) {
        setTimeout(() => {
            const tasks = this.taskData();
            const taskIndex = tasks.findIndex((t) => t.id === task.id);
            if (taskIndex !== -1) {
                const updatedTask = { ...tasks[taskIndex], status: completed ? 'completed' : 'pending', completed };
                const remainingTasks = tasks.filter((t) => t.id !== task.id);
                this.taskData.set([updatedTask, ...remainingTasks]);
            }
        }, 400);
    }

    deleteTask(taskId: number) {
        this.confirmationService.confirm({
            message: 'Are you sure you want to delete this task?',
            header: 'Delete Confirmation',
            icon: 'pi pi-info-circle',
            rejectButtonProps: {
                label: 'Cancel',
                severity: 'secondary',
                outlined: true
            },
            acceptButtonProps: {
                label: 'Delete',
                severity: 'danger'
            },
            accept: () => {
                const tasks = this.taskData().filter((task) => task.id !== taskId);
                this.taskData.set(tasks);
            }
        });
    }

    openNewTaskDrawer() {
        this.selectedTask = null;
        this.drawerMode = 'create';
        this.isDrawerVisible = true;
    }

    openEditTaskDrawer(task: Task) {
        this.selectedTask = task;
        this.drawerMode = 'edit';
        this.isDrawerVisible = true;
    }

    handleDrawerSave(newTaskData: any) {
        if (this.drawerMode === 'create') {
            const tasks = this.taskData();
            const newId = Math.max(...tasks.map((t) => t.id), 0) + 1;
            const newTask: Task = {
                id: newId,
                title: newTaskData.title || '',
                description: newTaskData.description || null,
                status: newTaskData.status || 'pending',
                completed: newTaskData.completed || false,
                startDate: newTaskData.startDate || null,
                endDate: newTaskData.endDate || null,
                members: newTaskData.members || []
            };
            this.taskData.set([newTask, ...tasks]);
        } else {
            const tasks = this.taskData();
            const taskIndex = tasks.findIndex((t) => t.id === newTaskData.id);
            if (taskIndex !== -1) {
                tasks[taskIndex] = {
                    ...tasks[taskIndex],
                    ...newTaskData,
                    id: tasks[taskIndex].id
                };
                this.taskData.set([...tasks]);
            }
        }
        this.isDrawerVisible = false;
    }

    handleDrawerCancel() {
        this.isDrawerVisible = false;
        this.selectedTask = null;
    }
}

type DataPoint = {
    x: Date;
    y: number | number[] | any;
};

export type TimeUnit = 'millisecond' | 'second' | 'minute' | 'hour' | 'day' | 'week' | 'month' | 'quarter' | 'year' | string;

export const parseDate = (dateStr: string | Date): Date => {
    return typeof dateStr === 'string' ? new Date(dateStr) : dateStr;
};

export const sampleDataReduction = (data: DataPoint[], option: TimeUnit, show: number): DataPoint[] => {
    const sampledData: DataPoint[] = [];
    let tempData: DataPoint[] = data.filter((item) => parseDate(item.x) >= startDate);
    const dataLength: number = data.length;

    if (dataLength === 0) return sampledData;

    const timeUnits: Record<TimeUnit, number> = {
        millisecond: 1,
        second: 1000,
        minute: 60 * 1000,
        hour: 60 * 60 * 1000,
        day: 24 * 60 * 60 * 1000,
        week: 7 * 24 * 60 * 60 * 1000,
        month: 30 * 24 * 60 * 60 * 1000,
        quarter: 90 * 24 * 60 * 60 * 1000,
        year: 365 * 24 * 60 * 60 * 1000
    };

    const selectedMultiplier: number = timeUnits[option];
    const endDate: Date = parseDate(data[dataLength - 1].x);
    const firstData: Date = parseDate(data[0].x);
    const calculatedDate: Date = new Date(endDate.getTime() - show * selectedMultiplier);
    const startDate: Date = firstData.getTime() > calculatedDate.getTime() ? firstData : calculatedDate;

    const tempLen: number = tempData.length;

    if (['minute', 'second', 'millisecond'].includes(option)) {
        if (tempLen < show) {
            const adjustedStartDate: Date = new Date(endDate);
            adjustedStartDate.setHours(endDate.getHours() - 4);
            tempData = data.filter((item) => parseDate(item.x) >= adjustedStartDate);
        }
        return tempData;
    } else if (['day', 'hour'].includes(option)) {
        return tempData;
    } else if (['week', 'month', 'quarter', 'year'].includes(option)) {
        // Define slice units for sampling
        const sliceUnits: Record<'week' | 'month' | 'quarter' | 'year', number> = {
            week: 7,
            month: 30,
            quarter: 90,
            year: 365 / 2
        };

        // Check if the `option` is present in `sliceUnits`
        if (option in sliceUnits) {
            const selectedSlicer: number = sliceUnits[option as keyof typeof sliceUnits];
            for (let i = 0; i < tempLen; i += selectedSlicer) {
                const range = tempData.slice(i, i + selectedSlicer);
                const rangeAverage =
                    range.reduce((sum, value) => {
                        return sum + (value.y as number); // Assume `y` is a number (not array)
                    }, 0) / range.length;

                sampledData.push({ x: range[0].x, y: rangeAverage });
            }
            return sampledData;
        }
    }

    return data; // Default fallback
};

export const sampleDataReductionByArray = (data: DataPoint[], option: TimeUnit, show: number): DataPoint[] => {
    const sampledData: DataPoint[] = [];
    const dataLength: number = data.length;

    if (dataLength === 0) return sampledData;

    const timeUnits: Record<TimeUnit, number> = {
        millisecond: 1,
        second: 1000,
        minute: 60 * 1000,
        hour: 60 * 60 * 1000,
        day: 24 * 60 * 60 * 1000,
        week: 7 * 24 * 60 * 60 * 1000,
        month: 30 * 24 * 60 * 60 * 1000,
        quarter: 90 * 24 * 60 * 60 * 1000,
        year: 365 * 24 * 60 * 60 * 1000
    };

    const selectedMultiplier: number = timeUnits[option];
    const endDate: Date = parseDate(data[dataLength - 1].x);
    const firstData: Date = parseDate(data[0].x);
    const calculatedDate: Date = new Date(endDate.getTime() - show * selectedMultiplier);
    const startDate: Date = firstData.getTime() > calculatedDate.getTime() ? firstData : calculatedDate;

    let tempData: DataPoint[] = data.filter((item) => parseDate(item.x) >= startDate);
    const tempLen: number = tempData.length;

    if (['minute', 'second', 'millisecond'].includes(option)) {
        if (tempLen < show) {
            const adjustedStartDate: Date = new Date(endDate);
            adjustedStartDate.setHours(endDate.getHours() - 4);
            tempData = data.filter((item) => parseDate(item.x) >= adjustedStartDate);
        }
        return tempData;
    } else if (['day', 'hour'].includes(option)) {
        return tempData;
    } else if (['week', 'month', 'quarter', 'year'].includes(option)) {
        const sliceUnits: Record<'week' | 'month' | 'quarter' | 'year', number> = {
            week: 7,
            month: 30,
            quarter: 90,
            year: 366 / 2
        };

        // Check if the `option` is present in `sliceUnits`
        if (option in sliceUnits) {
            const selectedSlicer: number = sliceUnits[option as keyof typeof sliceUnits];
            for (let i = 0; i < tempLen; i += selectedSlicer) {
                let sampledPointY: number | number[];

                // Handle case where the `y` value is an array
                if (Array.isArray(tempData[i].y)) {
                    sampledPointY = [...(tempData[i].y as number[])]; // Copy array to avoid mutation
                } else {
                    sampledPointY = tempData[i].y as number;
                }

                sampledData.push({ x: tempData[i].x, y: sampledPointY });
            }
        }
        return sampledData;
    }

    return data;
};

// Function 3: sampleDataByFixedLength
export const sampleDataByFixedLength = (data: any, option: any, show: any): any => {
    const sampledData: any = [];
    const dataLength = data.length;

    if (dataLength === 0) return sampledData;

    const timeUnits: any = {
        millisecond: 'millisecond',
        second: 'second',
        minute: 'minute',
        hour: 'hour',
        day: 'day',
        week: 'week',
        month: 'month',
        quarter: 'quarter',
        year: 'year'
    };

    if (!timeUnits[option]) return data;

    const parseDate = (dateStr: any) => new Date(dateStr);

    const average = (arr: any) => {
        if (arr.length === 0) return 0;
        if (typeof arr[0] === 'number') {
            return arr.reduce((acc: any, val: any) => acc + val, 0) / arr.length;
        } else {
            const length = arr[0].length;

            const avgArr: any = [];
            Array(length)
                .fill(null)
                .forEach((_, i) => {
                    const val = arr.map((data: any) => Number(data[i])).reduce((acc: any, val: any) => acc + val, 0) / arr.length;
                    avgArr.push(val);
                });
            return avgArr;
        }
    };

    let tempData = [];
    let currentUnit = null;

    for (let i = dataLength - 1; i >= 0; i--) {
        const dataPoint = data[i];
        const date = parseDate(dataPoint.x);

        let unit = null;
        if (option === 'day') {
            unit = Math.floor(date.getTime() / (24 * 60 * 60 * 1000));
        } else if (option === 'week') {
            unit = Math.floor(date.getTime() / (7 * 24 * 60 * 60 * 1000));
        } else if (option === 'month') {
            unit = date.getFullYear() * 12 + date.getMonth();
        } else if (option === 'year') {
            unit = date.getFullYear();
        } else if (option === 'hour') {
            unit = Math.floor(date.getTime() / (60 * 60 * 1000));
        } else if (option === 'minute') {
            unit = Math.floor(date.getTime() / (60 * 1000));
        } else if (option === 'second') {
            unit = Math.floor(date.getTime() / 1000);
        } else if (option === 'millisecond') {
            unit = Math.floor(date.getTime() / 1);
        } else if (option === 'quarter') {
            unit = date.getFullYear() * 4 + Math.floor(date.getMonth() / 3);
        }

        if (currentUnit === null) {
            currentUnit = unit;
        }

        if (unit !== currentUnit) {
            const avgValues = average(tempData.map((item) => item.y));
            sampledData.unshift({ x: tempData[0].x, y: avgValues });
            tempData = [];
            currentUnit = unit;
        }

        tempData.push(dataPoint);

        if (sampledData.length >= show) {
            break;
        }
    }

    if (tempData.length > 0) {
        const avgValues = average(tempData.map((item) => item.y));
        sampledData.unshift({ x: tempData[0].x, y: avgValues });
    }
    if (['week', 'month', 'quarter'].includes(option)) {
        const days: any = {
            week: 7,
            month: 30,
            quarter: 90
        };
        const dayCn = 24 * 60 * 60 * 1000;
        if (new Date(sampledData[sampledData.length - 1].x).getTime() / dayCn - new Date(sampledData[sampledData.length - 2].x).getTime() / dayCn < days[option]) {
            sampledData.pop();
        } else {
            sampledData.shift();
        }
    }
    return sampledData;
};

// Function 4: generateRandomData
export const generateRandomData = (startDate: string | Date, endDate: string | Date, intervalHours: number, minValue: number, maxValue: number): DataPoint[] => {
    const data: DataPoint[] = [];
    let currentDate: Date = parseDate(startDate);
    const end: Date = parseDate(endDate);

    while (currentDate <= end) {
        const currentValue: number = minValue + Math.random() * (maxValue - minValue);
        data.push({ x: new Date(currentDate), y: parseFloat(currentValue.toFixed(2)) });
        currentDate = new Date(currentDate.getTime() + intervalHours * 60 * 60 * 1000);
    }

    return data;
};

// Function 5: generateRandomMultiData
export const generateRandomMultiData = (startDate: string | Date, endDate: string | Date, intervalHours: number, minValue: number, maxValue: number, datasetsCount: number = 2, inter: boolean = false): DataPoint[] => {
    const data: DataPoint[] = [];
    let currentDate: Date = parseDate(startDate);
    const end: Date = parseDate(endDate);

    while (currentDate <= end) {
        let currentValues;
        if (inter) {
            const incr = maxValue;
            currentValues = Array(datasetsCount)
                .fill(null)
                .map((_, i) => {
                    return (minValue + Math.random() * (maxValue - minValue) + incr * (datasetsCount - i * 1.2)).toFixed(0);
                });
        } else {
            currentValues = Array(datasetsCount)
                .fill(null)
                .map(() => {
                    return (minValue + Math.random() * (maxValue - minValue)).toFixed(0);
                });
        }
        data.push({ x: new Date(currentDate), y: [...currentValues] });

        currentDate = new Date(currentDate.getTime() + intervalHours * 60 * 60 * 1000);
    }
    return data;
};

export const trackByFn = (): string => {
    const timestamp = Date.now();
    const randomNum = Math.random().toString(36).substring(2, 8);
    const uniqueId = `${timestamp}-${randomNum}`;

    return uniqueId;
};

export function isoDayOfWeek(dt: any) {
    let wd = dt.getDay();
    wd = ((wd + 6) % 7) + 1;
    return '' + wd;
}

export const generateRandomHeatmapData = () => {
    const today = new Date(2024, 8, 20);
    const end = today;
    let dt = new Date(end);
    dt.setDate(end.getDate() - 81);
    const data2 = [];

    while (dt <= end) {
        const iso = dt.toISOString().substring(0, 10);
        data2.push({
            x: iso,
            y: isoDayOfWeek(dt),
            d: iso,
            v: Math.floor(Math.random() * (1501 - 200)) + 200
        });
        dt = new Date(dt.setDate(dt.getDate() + 1));
    }
    return data2;
};
